// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// ListProductCategories Daftar kategori produk
	// (GET /api/v1/product-categories)
	ListProductCategories(ctx context.Context, request ListProductCategoriesRequestObject) (ListProductCategoriesResponseObject, error)
	// CreateProductCategory Membuat kategori produk (kode unik permanen)
	// (POST /api/v1/product-categories)
	CreateProductCategory(ctx context.Context, request CreateProductCategoryRequestObject) (CreateProductCategoryResponseObject, error)
	// DeleteProductCategory Menghapus kategori (soft delete)
	// (DELETE /api/v1/product-categories/{id})
	DeleteProductCategory(ctx context.Context, request DeleteProductCategoryRequestObject) (DeleteProductCategoryResponseObject, error)
	// UpdateProductCategory Mengubah nama kategori
	// (PUT /api/v1/product-categories/{id})
	UpdateProductCategory(ctx context.Context, request UpdateProductCategoryRequestObject) (UpdateProductCategoryResponseObject, error)
	// RestoreProductCategory Memulihkan kategori yang dihapus (hanya Admin Sistem)
	// (POST /api/v1/product-categories/{id}/restore)
	RestoreProductCategory(ctx context.Context, request RestoreProductCategoryRequestObject) (RestoreProductCategoryResponseObject, error)
	// ListProducts Daftar produk (Produk Jadi, Packaging, Material, Bundling)
	// (GET /api/v1/products)
	ListProducts(ctx context.Context, request ListProductsRequestObject) (ListProductsResponseObject, error)
	// CreateProduct Membuat produk (MD-01, MD-02, MD-03)
	// (POST /api/v1/products)
	CreateProduct(ctx context.Context, request CreateProductRequestObject) (CreateProductResponseObject, error)
	// LookupProduct Mencari satu produk aktif berdasarkan SKU atau barcode persis (pindai barcode)
	// (GET /api/v1/products/lookup)
	LookupProduct(ctx context.Context, request LookupProductRequestObject) (LookupProductResponseObject, error)
	// DeleteProduct Menghapus produk (soft delete; tetap tampil di dokumen lama)
	// (DELETE /api/v1/products/{id})
	DeleteProduct(ctx context.Context, request DeleteProductRequestObject) (DeleteProductResponseObject, error)
	// GetProduct Detail produk (produk terhapus tetap bisa dibuka untuk dokumen lama)
	// (GET /api/v1/products/{id})
	GetProduct(ctx context.Context, request GetProductRequestObject) (GetProductResponseObject, error)
	// UpdateProduct Mengubah produk (optimistic locking dengan `version`)
	// (PUT /api/v1/products/{id})
	UpdateProduct(ctx context.Context, request UpdateProductRequestObject) (UpdateProductResponseObject, error)
	// RestoreProduct Memulihkan produk yang dihapus (hanya Admin Sistem)
	// (POST /api/v1/products/{id}/restore)
	RestoreProduct(ctx context.Context, request RestoreProductRequestObject) (RestoreProductResponseObject, error)
}

